                if self._purge_locked():
                    self._persist_locked()
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            LOG.warning("could not load data file %s: %s; starting empty", self.path, exc)
            self.entries = {}

    def put(self, key, value, ttl):
